#!/usr/bin/env python3
"""Build the static pages from data/library.json. No third-party Python packages required."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];D=json.loads((ROOT/'data/library.json').read_text());C=D['colors'];esc=html.escape
TOTAL=sum(c['total'] for c in C);BODY=sum(c['body_count'] for c in C)
MARK='<svg width="27" height="30" viewBox="0 0 27 30" fill="none" aria-hidden="true"><path d="M2 13.5 13.5 3 25 13.5V27H2V13.5Z" stroke="currentColor" stroke-width="1.6"/><path d="M8 27V17h11v10M7 11h13" stroke="currentColor" stroke-width="1.6"/></svg>'
ARROW='<span aria-hidden="true">↗</span>'
def photo(c):return next(p for g in c['groups'] for p in g['photos'] if p['id']==c['hero'])
def header(base,active=''):
 return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="{base}index.html">{MARK}<span>The Exterior<br><b>Paint Library</b></span></a><nav aria-label="Main navigation"><a class="{'active' if active=='colors' else ''}" href="{base}index.html#colors">The colors</a><a class="{'active' if active=='library' else ''}" href="{base}library/">All photos</a><a class="{'active' if active=='about' else ''}" href="{base}about/">About the research</a><a class="preview-link" href="{base}house-preview/">House preview</a><a class="saved-link" href="{base}library/?saved=1">Saved <span data-saved-count>0</span></a></nav></header>'''
def footer(base):
 return f'''<footer class="site-footer"><div><a class="brand" href="{base}index.html">{MARK}<span>The Exterior<br><b>Paint Library</b></span></a><p>Color makes more sense on a real home.</p></div><div class="footer-colors">{''.join(f'<a href="{base}colors/{c["slug"]}/">{esc(c["name"])}</a>' for c in C)}</div><div class="footer-note"><p>An independent visual reference.<br>Photos belong to their respective creators.<br>Source links and attribution accompany every project.</p><a href="https://github.com/brendansudol/exterior-paint-library">View on GitHub ↗</a></div><div class="footer-bottom"><span>Research updated October 9, 2026</span><span>Not affiliated with Sherwin-Williams. Swatches are approximate.</span></div></footer>'''
def dialogs():return '''<dialog class="lightbox" id="viewer" aria-label="Photo viewer"><div class="viewer-top"><span id="viewer-position"></span><button class="icon-button" id="viewer-close" aria-label="Close photo">✕</button></div><div class="viewer-layout"><div class="viewer-image-wrap"><img id="viewer-image" alt=""><button class="viewer-arrow previous" id="viewer-prev" aria-label="Previous photo">←</button><button class="viewer-arrow next" id="viewer-next" aria-label="Next photo">→</button></div><aside class="viewer-info" id="viewer-info"></aside></div></dialog><div class="toast" id="toast" role="status" aria-live="polite"></div>'''
def page(path,title,body,base='./',active='',kind='home',slug=''):
 out=ROOT/path;out.parent.mkdir(parents=True,exist_ok=True)
 out.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#243c33"><meta name="description" content="Explore real house exteriors in six Sherwin-Williams paint colors. {TOTAL} sourced images, original project links and clear color evidence."><title>{esc(title)} · The Exterior Paint Library</title><link rel="icon" type="image/svg+xml" href="{base}assets/favicon.svg"><link rel="stylesheet" href="{base}assets/site.css"><script src="{base}assets/app.js" defer></script></head><body data-base="{base}" data-page="{kind}" data-color="{slug}">{header(base,active)}<main id="main">{body}</main>{footer(base)}{dialogs()}</body></html>''')
hero=C[0];hp=photo(hero)
body=f'''<section class="home-hero"><div class="hero-copy"><p class="eyebrow"><span class="tiny-rule"></span> A study in exterior color</p><h1>A color.<br>A house.<br><em>A different feeling.</em></h1><p class="intro">Six shades of green and blue, out in the world. Explore real homes, changing light, and the details that make each color its own.</p><a class="button dark" href="#colors">Find your color <span>↓</span></a><div class="hero-stats"><span><b>06</b> paint colors</span><span><b>{TOTAL}</b> collected images</span><span><b>{BODY}</b> body & siding views</span></div></div><figure class="hero-photo"><img src="{hp['file']}" alt="Acacia Haze siding with white trim on a real home in Bothell, Washington" fetchpriority="high"><figcaption><span><i style="background:{hero['swatch']}"></i> Acacia Haze <small>SW 9132</small></span><a href="colors/acacia-haze/">Explore this color ↗</a></figcaption><div class="image-stamp">REAL HOMES<br>REAL CONTEXT</div></figure></section>
<section class="house-preview-promo" aria-label="House color studio"><div><p class="eyebrow">The house color studio</p><h2>See the shortlist<br>on one house.</h2><p>Switch between six paints and 22 appearances sampled from real photographs. Compare three views with new lap siding, white trim and a natural wood door.</p><a class="button dark" href="house-preview/">Open the house preview <span>→</span></a><small>Illustrative renovation simulations. Photo samples include lighting and camera effects.</small></div><a class="house-preview-image" href="house-preview/" aria-label="Open house color preview"><img src="house-preview/images/front-acacia-haze.webp" alt="Illustrative Acacia Haze renovation preview with lap siding and white trim" loading="lazy"><span>Renovation simulation · 6 paints / 3 views</span></a></section>
<section id="colors" class="color-section"><div class="section-heading"><div><p class="eyebrow">The collection / 01—06</p><h2>Start with a shade.</h2></div><p>See it across houses, materials and light.<br>Every collection keeps the evidence close.</p></div><div class="color-grid">'''
for i,c in enumerate(C,1):
 p=photo(c)
 body+=f'''<a class="color-card" href="colors/{c['slug']}/"><div class="color-card-image"><img src="{p['thumb']}" alt="{esc(c['name'])} house exterior" loading="lazy"><span class="card-index">0{i}</span><span class="paint-chip" style="background:{c['swatch']}" aria-hidden="true"></span></div><div class="color-card-text"><div><span class="color-code">SHERWIN-WILLIAMS / {c['code']}</span><h3>{esc(c['name'])}</h3></div><span class="round-arrow">↗</span><p>{esc(c['description'])}</p><div class="card-meta"><span>{c['body_count']} body & siding views</span><span>{c['total']} images total</span></div></div></a>'''
body+=f'''</div></section><section class="context-section"><p class="eyebrow">A little context goes a long way</p><h2>More than a paint chip.</h2><div class="context-grid"><div><span>01 / In place</span><h3>Homes, not mockups.</h3><p>Explore the color on siding, stucco, doors and trim. Construction stages, television stills and uncertain examples are clearly labeled.</p></div><div><span>02 / In the light</span><h3>One color, many moods.</h3><p>Sun, shade, materials and cameras change the way a color appears. Compare several projects before choosing a sample for your own home.</p></div><div><span>03 / With a source</span><h3>Follow the evidence.</h3><p>Project sources, paint palettes and photo credits stay attached. Secondary color attributions are kept distinct from source-confirmed examples.</p></div></div><a class="text-link" href="about/">How this collection was researched ↗</a></section>'''
page('index.html','Real homes. Six exterior paint colors.',body,active='colors')
def controls(color=None):
 opts='<option value="all">All six colors</option>'+''.join(f'<option value="{c["slug"]}">{esc(c["name"])}</option>' for c in C)
 return f'''<section class="browse-controls" aria-label="Photo filters"><div class="filter-top"><label class="search-field"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Search siding, white trim, project or place…" aria-label="Search photos"></label>{'' if color else f'<label class="select-field"><span class="sr">Paint color</span><select id="color-select">{opts}</select></label>'}<button class="saved-toggle" id="saved-toggle" aria-pressed="false">♡ Saved only</button></div><div class="filter-bottom"><div class="filter-tabs" role="group" aria-label="Photo category"><button data-filter="body" class="selected">Body & siding</button><button data-filter="confirmed">Source-confirmed body</button><button data-filter="attributed">Other body attributions</button><button data-filter="accents">Doors & accents</button><button data-filter="all">Everything</button></div><span class="result-count" id="result-count" aria-live="polite"></span></div></section><div class="browse-note"><span class="evidence-dot"></span><p id="filter-note">Body photos include source-confirmed and secondary-attributed projects. Each is labeled below.</p></div><div id="gallery" class="gallery"><p class="loading">Opening the photo library…</p></div><noscript><p>This searchable view needs JavaScript. All original research galleries are linked below.</p></noscript>'''
for c in C:
 base='../../';p=photo(c);count=c['counts']
 color_nav=''
 for x in C:color_nav+=f'<a class="{"current" if x==c else ""}" href="../{x["slug"]}/" '+('aria-current="page"' if x==c else '')+f'><i style="background:{x["swatch"]}"></i>{esc(x["name"])}</a>'
 body=f'''<nav class="color-rail" aria-label="Paint collections">{color_nav}</nav><section class="collection-hero"><div class="collection-copy"><a class="back-link" href="../../index.html#colors">← The six colors</a><p class="eyebrow">Sherwin-Williams / {c['code']}</p><h1>{esc(c['name'])}</h1><p class="intro">{esc(c['description'])}</p><a class="text-link collection-preview" href="../../house-preview/#view=front&amp;a={c['slug']}&amp;mode=single">Preview this color on the house →</a><div class="collection-stats"><span><b>{c['body_count']}</b>body & siding views</span><span><b>{count['accents']}</b>door & accent views</span><span><b>{c['total']}</b>images in this collection</span></div></div><div class="collection-photo"><img src="{base}{p['file']}" alt="{esc(c['name'])} exterior from the photo collection" fetchpriority="high"><div class="collection-swatch" style="background:{c['swatch']}"><span>{c['code']}</span></div></div></section><section class="browse-section"><div class="section-heading compact"><div><p class="eyebrow">The photographs</p><h2>See it on a home.</h2></div><p>Click a photo for the full view and its source.<br>Use ♡ to keep a personal shortlist.</p></div>{controls(c)}</section><section class="research-section"><p class="eyebrow">Keep exploring</p><h2>Go back to the sources.</h2><p>Read the original research notes, exclusions and project evidence behind this collection.</p><div class="research-links"><a class="button outline" href="{base}research/{c['slug']}/{c['slug']}-exterior-photos.html">Original research gallery ↗</a><a class="text-link" href="{base}research/{c['slug']}/sources.json" download>Download source manifest ↓</a></div><details><summary>Search coverage & limitations</summary><p>{esc(c['methodology'])}</p></details></section>'''
 page(f'colors/{c["slug"]}/index.html',f'{c["name"]} {c["code"]} exterior photos',body,base,kind='color',slug=c['slug'])
body=f'''<section class="library-heading"><p class="eyebrow">Every color, in one place</p><h1>The photo library.</h1><p class="intro">{TOTAL} collected images. Six colors. Search across the collection or save the views you want to come back to.</p></section><section class="browse-section library-browse">{controls()}</section><section class="research-section"><p class="eyebrow">More context</p><h2>Every photo has a story.</h2><p>Some colors are identified by the painter or homeowner. Others come from a secondary source. The labels help you tell them apart.</p><a class="text-link" href="../about/">Read about the research ↗</a></section>'''
page('library/index.html','Explore all exterior photos',body,'../',active='library',kind='library')
body=f'''<section class="about-heading"><p class="eyebrow">About the collection</p><h1>Useful pictures.<br><em>Honest context.</em></h1><p class="intro">An independent collection of real house exteriors in six Sherwin-Williams colors, assembled to make paint research easier to see.</p></section><section class="about-body"><div class="about-aside"><span>{TOTAL}</span><p>collected image assets</p><span>{BODY}</span><p>body and siding views</p><small>Image counts are not house counts. One project can have several photographs.</small></div><div class="about-prose"><h2>What the labels mean</h2><h3>Source-confirmed body</h3><p>A painter, designer, homeowner, builder or production company names the paint used on the house body. This is confirmation from the source, not a physical test of paint chemistry.</p><h3>Secondary attribution</h3><p>A publication or social post labels the pictured color, but an original project paint statement was not recovered. These images remain useful references with a lower level of certainty.</p><h3>Doors & accents</h3><p>The color appears on a door, shutter, porch element or other accent. The main siding may use a different paint color. Read the palette and evidence for each project.</p><h3>Uncertain examples & sample boards</h3><p>These appear only under Everything, with separate labels. They are excluded from the body and siding totals. Uncertain examples can include unresolved paint stages, proposed specifications or digitally altered listing elements.</p><h2>How the photos were collected</h2><p>The research covered public web and image search, painter and builder portfolios, homeowner posts, project albums, property listings and design publications. Where possible, reposts were traced back to original project sources. Known duplicate images were removed within each collection; distinct angles and labeled comparison panels were retained.</p><p>Each color’s original research gallery and source manifest remain available. The manifests record image URLs, original source pages, evidence notes and checksums for the downloaded files.</p><h2>Reading color in a photograph</h2><p>Lighting, surroundings, camera processing and your screen affect what you see. The research collection photographs have not been recolored. The separate <a class="text-link" href="../house-preview/">house color studio</a> contains clearly labeled renovation simulations, including 22 appearances sampled from real photos. Those samples include the source lighting and camera treatment; they are not calibrated paint predictions. Smaller previews are resized and compressed for browsing; the viewer links to the original downloaded image. Paint swatches are approximate navigation aids. Try a physical sample outdoors before deciding.</p><h2>Credits & use</h2><p>Photographs belong to their respective creators. Credits and source links travel with the images; this collection does not grant a reuse license. This independent reference is not affiliated with or endorsed by Sherwin-Williams.</p><h2>Research archive</h2><div class="archive-list">'''+''.join(f'<a href="../research/{c["slug"]}/{c["slug"]}-exterior-photos.html"><span>{c["name"]}</span><span>{c["total"]} images ↗</span></a>' for c in C)+'''</div><p class="muted">Researched October 8–9, 2026. Public, accessible sources only; private, deleted, inaccessible or unindexed images may exist beyond the collection.</p></div></section>'''
page('about/index.html','About the research',body,'../',active='about',kind='about')
page('404.html','Page not found','<section class="library-heading"><p class="eyebrow">A small detour</p><h1>That page isn’t here.</h1><p class="intro">Head back to the collection to find a color.</p><a class="button dark" href="/exterior-paint-library/">Back to the library →</a></section>','/exterior-paint-library/')
for c in C:
 archive=ROOT/'research'/c['slug']/(c['slug']+'-exterior-photos.html')
 old=archive.read_text()
 bar=f'<div style="padding:13px 32px;background:#243c33;color:#f6f4ef;font:13px -apple-system,sans-serif;display:flex;gap:25px;flex-wrap:wrap"><a style="color:inherit" href="../../index.html">← The Exterior Paint Library</a><a style="color:inherit" href="../../colors/{c["slug"]}/">New {c["name"]} collection ↗</a><span>Original research gallery</span></div>'
 if 'New '+c['name']+' collection' not in old: archive.write_text(old.replace('<body>','<body>'+bar,1))
(ROOT/'.nojekyll').touch()
print(f'Built 10 pages for {TOTAL} images / {BODY} body views.')
